  "pa.dismissKeys": "Clique ou appuie sur Échap pour fermer",
  "pa.hello.center-perks.0": "Bonjour, Center Perks ! Menton haut, lits faits, sourire aux lèvres.",
  "pa.hello.center-perks.1": "Bonjour à tous. Ici le directeur Hartley, avec les avis du jour.",
  "pa.hello.center-perks.2": "Bonjour. Quelqu’un a encore laissé une chaussette dans la soupe. Encore.",
  "pa.hello.stalag-flucht.0": "Achtung, prisonniers ! Belle matinée bien fraîche. Profitez-en, côté barbelés.",
  "pa.hello.stalag-flucht.1": "Achtung. Voici les ordres du jour du Kommandant.",
  "pa.hello.stalag-flucht.2": "Achtung ! Cette nuit, quelqu’un a creusé jusqu’à la cuisine. La cuisine. Ach.",
  "pa.hello.shankton.0": "Debout, Shankton. Belle journée pour respecter le règlement.",
  "pa.hello.shankton.1": "Ici la directrice Kroll. Écoutez bien, je ne le dirai qu’une fois.",
  "pa.hello.shankton.2": "Ici Kroll. Je n’ai pas eu mon café. Ne me cherchez pas.",
  "pa.hello.san-pancho.0": "¡Buenos días, mis amigos ! El Jefe vous aime tous. Enfin, presque.",
  "pa.hello.san-pancho.1": "Ici El Jefe. Les nouvelles du jour, depuis le sommet.",
  "pa.hello.san-pancho.2": "El Jefe n’est pas content. On lui a volé son hamac préféré.",
  "pa.hello.irongate.0": "Bonjour, résidents d’Irongate. La mer vous salue.",
  "pa.hello.irongate.1": "Gouverneur Ashcombe. Les dispositions du jour sont les suivantes.",
  "pa.hello.irongate.2": "Ici le gouverneur. Mon thé était froid. Vous voilà tous prévenus.",
  "pa.first.center-perks": "Bienvenue à Center Perks, le nouveau. Suis la cloche et on s’entendra bien.",
  "pa.first.stalag-flucht": "Bienvenue au Stalag Flucht. L’évasion est interdite. Et puis il fait très froid.",
  "pa.first.shankton": "Bienvenue à Shankton. Murs : épais. Gardiens : nombreux. Questions : aucune.",
  "pa.first.san-pancho": "Bienvenue à San Pancho, amigo ! Attention aux mines, au soleil, et à El Jefe.",
  "pa.first.irongate": "Bienvenue à Irongate. Personne ne part. La mer y veille.",
  "pa.morning.none": "Rien de spécial aujourd’hui. Restons ennuyeux.",
  "pa.morning.inspection": "Les inspecteurs du ministère arrivent à {time}. Cellules propres, manières propres.",
