  "rumor.gardenHole": "Un trou creusé à travers un carré planté du potager : aucun gardien ne le voit sous la plante.",
  "rumor.phoneCall": "{inmate} appelle chez lui vers {t1} : reste près du téléphone et tu entendras des choses.",
  "rumor.raceNight": "Courses de rats au bloc des cellules les soirs impairs à {t1} : apporte de l’argent.",
  "rumor.ratFed": "Le rat de {inmate} a bien mangé aujourd’hui : il va filer ce soir.",
  "rumor.ratHungry": "Le rat de {inmate} n’a pas touché à sa gamelle aujourd’hui.",
  // P28 lessons: pruno, the garden, rat racing.
  "lesson.pruno.t": "Le pruno",
  "lesson.pruno.d": "Le brasser, le cacher, l’attendre",
  "lesson.pruno.brew": "Des fruits (au comptoir de la cantine, aux repas) et du sucre (à la cuisine, ou chez un marchand) font du pruno. Ouvre l’atelier (%KeyC%) et brasse un sac avec tes deux fruits et le sucre",
  "lesson.pruno.brewTouch": "Des fruits (au comptoir de la cantine, aux repas) et du sucre (à la cuisine, ou chez un marchand) font du pruno. Ouvre l’atelier (le bouton marteau) et brasse un sac avec tes deux fruits et le sucre",
  "lesson.pruno.hide": "Il ne fermente que hors de tes poches. Cache-le dans le réservoir de ton WC (%KeyE%) : les fouilles n’y regardent jamais, mais un chien qui passe le flaire",
  "lesson.pruno.hideTouch": "Il ne fermente que hors de tes poches. Cache-le dans le réservoir de ton WC (le bouton d’action) : les fouilles n’y regardent jamais, mais un chien qui passe le flaire",
  "lesson.pruno.sleep": "Deux nuits pour mûrir. Le sac caché dans ton bureau il y a deux nuits sera prêt au matin : dors dans ton lit (%KeyE%)",
  "lesson.pruno.sleepTouch": "Deux nuits pour mûrir. Le sac caché dans ton bureau il y a deux nuits sera prêt au matin : dors dans ton lit (le bouton d’action)",
  "lesson.pruno.drink": "Prêt ! Prends-le dans le tiroir caché de ton bureau et bois-le : Espace deux fois, le pruno en main (la première demande si tu es sûr)",
  "lesson.pruno.drinkTouch": "Prêt ! Prends-le dans le tiroir caché de ton bureau et bois-le : le bouton Boire deux fois, le pruno en main (la première demande si tu es sûr)",
  "lesson.pruno.over": "Pompette pour 3 heures : des coups plus forts, une démarche plus lente, et un gardien qui te voit, c’est de la suspicion. Le pruno prêt se vend aussi 30 $, ou fait un beau cadeau",
  "lesson.garden.t": "Le potager",
  "lesson.garden.d": "Des graines, de l’eau et un secret",
  "lesson.garden.plant": "Les carrés du potager : face à un carré vide, appuie sur Espace avec le sachet de graines en main pour le planter",
  "lesson.garden.plantTouch": "Les carrés du potager : face à un carré vide, touche Planter avec le sachet de graines en main",
  "lesson.garden.water": "Arrose-le maintenant : le gobelet en main (2), Espace devant le carré. Chaque jour arrosé, il pousse",
  "lesson.garden.waterTouch": "Arrose-le maintenant : le gobelet en main, puis Arroser devant le carré. Chaque jour arrosé, il pousse",
  "lesson.garden.wilted": "Le carré du bout est resté un jour sans eau et a flétri : arrose-le aujourd’hui, sinon un deuxième jour à sec le tue",
  "lesson.garden.wiltedTouch": "Le carré du bout est resté un jour sans eau et a flétri : arrose-le aujourd’hui, sinon un deuxième jour à sec le tue",
  "lesson.garden.pick": "Celui-ci est mûr après trois jours arrosés : face à lui, appuie sur Espace, quoi que tu aies en main",
  "lesson.garden.pickTouch": "Celui-ci est mûr après trois jours arrosés : face à lui, touche Récolter, quoi que tu aies en main",
  "lesson.garden.secret": "Le secret du potager : un trou creusé à travers un carré planté se cache sous la plante, et aucun gardien ne le voit",
  "lesson.ratRace.t": "Courses de rats",
  "lesson.ratRace.d": "Entraîne ton rat, mise sur un gagnant",
  "lesson.ratRace.train": "Ton rat apprivoisé peut courir. Dans ta cellule, pendant le temps libre du soir, appuie sur Espace avec la piste à rat en main : il mange la patate et court",
  "lesson.ratRace.trainTouch": "Ton rat apprivoisé peut courir. Dans ta cellule, pendant le temps libre du soir, touche Entraîner avec la piste à rat en main : il mange la patate et court",
  "lesson.ratRace.go": "Les soirs impairs, il y a course : va à la piste du couloir",
  "lesson.ratRace.card": "Le programme de la course est affiché ici dès 19:00",
  "lesson.ratRace.enter": "Inscris ton rat à la course de ce soir avec le bouton du programme",
  "lesson.ratRace.enterTouch": "Inscris ton rat à la course de ce soir : touche le bouton du programme",
  "lesson.ratRace.bet": "Maintenant un pari : choisis une mise, puis Parier sur un rat. Un rat qui a mangé aujourd’hui fait mieux que sa cote, et le tien vient de manger",
  "lesson.ratRace.betTouch": "Maintenant un pari : touche une mise, puis Parier sur un rat. Un rat qui a mangé aujourd’hui fait mieux que sa cote, et le tien vient de manger",
  "lesson.ratRace.watch": "Départ à 21:00 : regarde la course",
  "lesson.ratRace.over": "Entraîne ton rat chaque soir pour qu’il soit plus rapide, et écoute les ragots : tes amis te disent quel rat a mangé aujourd’hui",
  "lesson.ratRace.off": "La course est annulée. Recommence la leçon",
  "lesson.ratRace.late": "Le programme est retiré : pas de pari ce soir. Recommence la leçon",
  "lesson.ratRace.broke": "Plus d’argent pour parier. Recommence la leçon",
