  "lesson.talent.t": "Soirée des talents",
  "lesson.talent.d": "Une chanson jouée en rythme, sur la scène de la cantine",
  "lesson.talent.watch": "C’est la soirée des talents : deux ou trois détenus jouent d’abord, et leur note s’affiche à la fin. Ton tour vient après le dernier numéro",
  "lesson.talent.stage": "Monte sur la scène, choisis une chanson et les batterie de seaux, puis appuie sur Jouer",
  "lesson.talent.stageTouch": "Monte sur la scène, choisis une chanson et les batterie de seaux, puis touche Jouer",
  "lesson.talent.play": "Joue chaque note quand elle arrive sur la ligne (%KeyA% %KeyS% %KeyD% ou ← ↓ →). En rythme, c’est parfait ; appuyer sans note proche te coûte des points",
  "lesson.talent.playTouch": "Touche la pastille d’une piste quand sa note arrive sur la ligne. En rythme, c’est parfait ; toucher sans note proche te coûte des points",
  "lesson.talent.over": "Ta note te classe parmi les numéros, pour un prix en argent. À 50 % ou plus, la salle t’estime davantage ; à 80 % ou plus, la bienveillance du directeur t’enlève 20 % de soupçon. Et la musique couvre le bruit à la cantine",
  "lesson.talent.late": "La soirée des talents est finie. Recommence la leçon",
  "lesson.talent.off": "Ton numéro a été interrompu. Recommence la leçon",
  "lesson.quiz.t": "Soirée quiz",
  "lesson.quiz.d": "Huit questions contre trois détenus",
  "lesson.quiz.join": "C’est la soirée quiz. À l’une des quatre places de la bibliothèque, appuie sur Participer : les trois détenus les plus proches viennent jouer",
  "lesson.quiz.answer": "Réponds avec 1–4 (ou clique). Pendant quelques secondes, le temps de la lire, chaque question est à toi seul ; ensuite, la première bonne réponse remporte le point. Qui se trompe est éliminé de la question",
  "lesson.quiz.answerTouch": "Touche une réponse. Pendant quelques secondes, le temps de la lire, chaque question est à toi seul ; ensuite, la première bonne réponse remporte le point. Qui se trompe est éliminé de la question",
  "lesson.quiz.play": "La moitié des questions porte sur des évasions célèbres, l’autre sur cette prison : son emploi du temps, ses gardiens, ce qu’on peut fabriquer. Joue jusqu’au bout",
  "lesson.quiz.over": "Celui qui a le plus de points gagne 30 $ et +2 d’Intelligence, et les candidats t’estiment davantage. Révise la prison, et Alcatraz",
  "lesson.quiz.late": "La soirée quiz est finie. Recommence la leçon",
  "lesson.quiz.off": "Tu as quitté le quiz. Recommence la leçon",
  "stage.firstPrize": "1er {n} $",
