  "hint.parole": "Ton audience est le jour {n}, dans {room}. D’ici là, tout va dans ton dossier : le travail, l’emploi du temps, les appels à la famille, les cours pour toi ; les bagarres, le mitard et les objets illicites contre. Pris à comploter, tout est annulé",
