  "look.paroleSpecs": "Lunettes de lecture",
  "lesson.parole.t": "La commission de libération",
  "lesson.parole.d": "Une semaine de bonne conduite, puis l’audience",
  "lesson.parole.go": "Tu as fait ta demande il y a une semaine. La commission siège à 10:00 dans la salle des visites : suis les flèches et prends place",
  "lesson.parole.read": "Chaque membre pose une question. Dessous, ton dossier montre ce qu’il dit : une affirmation qu’il confirme vaut le plus, un mensonge est démasqué. Réponds avec 1–3",
  "lesson.parole.readTouch": "Chaque membre pose une question. Dessous, ton dossier montre ce qu’il dit : une affirmation qu’il confirme vaut le plus, un mensonge est démasqué. Touche une réponse",
  "lesson.parole.rest": "Réponds aux deux autres. Ton dossier et tes réponses décident ensemble",
  "lesson.parole.over": "Accordée : ton nom est sur la liste de libération de demain. Présente-toi au guichet des libérations à 10:00 et sors dans tes propres vêtements",
  "lesson.parole.late": "Tu as manqué l’audience. Recommence la leçon",
  "lesson.parole.walked": "Tu as quitté la commission. Recommence la leçon",
  "lesson.parole.denied": "La commission a dit non. Recommence la leçon : lis ton dossier avant d’affirmer quoi que ce soit, et réponds à chaque question à temps",
  "help.parole.t": "La conditionnelle",
  "help.parole.hook": "Un dossier propre, une audience, la grande porte",
  "help.parole.sum": "Demande la conditionnelle, garde un dossier propre une semaine, puis convaincs la commission à l’audience.",
  "help.parole.tl": "Dès le jour 3|Demande au guichet des libérations\nUne semaine plus tard, 10:00|La commission siège\n10:30|Dernier moment pour arriver\nLe lendemain, 10:00|Présente-toi au guichet",
  "help.parole.steps": "À partir du jour 3, fais ta demande au guichet des libérations, ou fais-la déposer par ton avocat depuis le téléphone (60 $, un jour plus tôt).\nPendant une semaine, ce que tu fais va dans ton dossier : le travail, les cours, l’emploi du temps, les appels à la famille, les services rendus, le potager.\nLe jour venu, sois dans la salle où siège la commission entre 10:00 et 10:30 (suis les flèches).\nTrois membres posent chacun une question ; dessous, ton dossier montre ce qu’il dit. Choisis une réponse.\nAccordée : le lendemain à 10:00, présente-toi au guichet des libérations et sors.",
  "help.parole.lh": "Les trois réponses",
  "help.parole.list": "Affirmer : vaut le plus si ton dossier le confirme ; un mensonge est démasqué.\nAvouer : un peu, pour la plupart des membres.\nDe belles paroles : valent plus avec l’Intelligence.",
  "help.parole.nums": "7 jours|de la demande à l’audience\n16|points pour l’obtenir\n3 jours|à attendre après un refus",
  "help.parole.warn": "Les bagarres que tu commences, les K.-O., le mitard, les objets illicites trouvés, la suspicion du soir, les créneaux manqués et l’alerte d’un chien comptent contre toi.\nPris à comploter (travaux découverts, pinces ou pelle sur toi, dehors la nuit), la demande est annulée.",
  "help.parole.tip": "Lis ton dossier avant d’affirmer quoi que ce soit : une affirmation qu’il confirme est la meilleure réponse qui soit.",
  "help.parole.more": "La commission siège dans la salle des visites à Center Perks, dans la baraque du mess à Stalag Flucht, et à la cantine ailleurs.\nUn confinement à 10:00 repousse l’audience d’un jour ; la manquer ou partir te coûte la demande.\nRefusée, tu peux refaire une demande 3 jours plus tard, et le dossier repart de zéro.\nLe matin de la sortie, le guichet vérifie toujours ta suspicion et tes poches.\nL’Évasion du jour n’a pas de commission de libération.",
  // ---------------------------------------------------------------- P40 : le tableau des petits boulots
