  "look.copper": "Liseré cuivre",
  "look.saffron": "Liseré safran",
  "help.oddjobs.t": "Le tableau des petits boulots",
  "help.oddjobs.hook": "Des petits boulots contre argent, outils et services",
  "help.oddjobs.sum": "Un tableau en liège sur le mur de la cantine : trois boulots par jour, affichés par les détenus. Prends-en un à la fois, fais-le avant la fin du délai (1 à 3 jours), puis retourne voir celui qui l’a demandé pour ta paie.",
  "help.oddjobs.lh": "Les boulots",
  "help.oddjobs.list": "Le larcin : le sifflet d’un gardien dans ses poches, ou la tasse du chef dans le congélateur.\nLe dépôt, la livraison : un colis dans un bureau sans être vu, ou en main propre.\nLe coup monté : planque un paquet dans le bureau d’un rival ; les gardiens le fouillent à 19:00.\nLes parties arrangées : perdre (ou gagner) un bras de fer, une partie de Menteur ou de dames.\nLe courrier du rat, le tuyau, la course : un mot par rat, un appel anonyme, du sucre chez un marchand.\nLe gâteau, le guet : un gâteau par la visite ; faire le guet pendant que quelqu’un creuse.",
  "help.oddjobs.lh2": "Les histoires",
  "help.oddjobs.list2": "Chaque prison a son histoire : trois boulots pour un même détenu, à partir du jour 2, une étape par jour.\nSa carte est épinglée à côté des autres, et de courtes cartes racontent la suite.\nFinis-en une et tu gagnes un nouveau liseré de combinaison.",
  "help.oddjobs.nums": "1 à 3 jours|pour faire un boulot\n15–60 $|la paie\n19:00|la fouille d’un coup monté\n15 min|le trou à surveiller",
  "help.oddjobs.tip": "Certains boulots rapportent un objet rare, ou une dette : il rejoindra ton équipe quoi qu’il pense de toi, ou te donnera un outil quand tu la réclameras.",
  "help.oddjobs.warn": "Rate (hors délai, vu, mauvais résultat) et celui qui a demandé t’apprécie moins. Un coup monté découvert : +35 % de suspicion.",
  "help.oddjobs.more": "Le trafiquant a son propre boulot chaque jour : demande-lui pendant le temps libre (opinion 50).\nAu guet, siffle (B, ou la pastille du boulot) dès qu’un gardien approche.\nLa pastille du boulot montre l’étape en cours ; la page Aujourd’hui de ton dossier les liste toutes.\nPris à partir de 18:00, un boulot compte ses jours à partir du lendemain matin. Fait à temps (ou avec ce que tu dois apporter en main à 08:00), il attend que tu viennes le rendre.",
  "lesson.oddjob.t": "Petits boulots",
  "lesson.oddjob.d": "Un boulot du tableau des petits boulots, du début à la fin",
  "lesson.oddjob.board": "Le tableau en liège sur le mur de la cantine, c’est le tableau des petits boulots. Place-toi devant.",
  "lesson.oddjob.take": "Chaque carte dit qui demande, quoi, en combien de temps et pour combien. Prends la Livraison.",
  "lesson.oddjob.give": "Le colis est dans tes poches. Suis les flèches jusqu’au détenu à qui il est destiné, parle-lui (%KeyE%) et donne-le-lui.",
  "lesson.oddjob.giveTouch": "Le colis est dans tes poches. Suis les flèches jusqu’au détenu à qui il est destiné, touche-le pour lui parler et donne-le-lui.",
  "lesson.oddjob.back": "Livré. Retourne voir celui qui l’a demandé : parle-lui et rends le boulot.",
  "lesson.oddjob.over": "Payé ! De nouveaux boulots chaque matin, un à la fois. Le trafiquant a les siens, et chaque prison a son histoire.",
  "lesson.oddjob.wrong": "Ce n’est pas la Livraison : recommence la leçon.",
  "lesson.oddjob.lost": "Le boulot est perdu : recommence la leçon.",
  "rumor.boardJob": "{inmate} a affiché un boulot sur le tableau aujourd’hui.",
  "oddjob.chain.center-perks.title": "La montre de Doc",
  "oddjob.chain.center-perks.0": "Doc a perdu la montre de gousset de sa défunte femme. Mouse entend tout : apporte-lui ce colis et demande.",
  "oddjob.chain.center-perks.1": "Mouse dit qu’un gardien l’a ramassée dans la cour et la garde dans sa poche. Récupère-la pour Doc.",
  "oddjob.chain.center-perks.2": "Doc a retrouvé sa montre et veut une vraie partie : bats-le aux dames, sans pitié.",
  "oddjob.chain.center-perks.0.done": "Mouse empoche le colis : « Un gardien l’a. Dis à Doc de patienter. »",
  "oddjob.chain.center-perks.1.done": "Doc porte la montre à son oreille. Elle fait encore tic-tac. Il ne dit rien pendant longtemps.",
  "oddjob.chain.center-perks.2.done": "« À la loyale », dit Doc. « Je te dois un service, petit. »",
  "oddjob.chain.stalag-flucht.title": "Le tunnel de Ferret",
  "oddjob.chain.stalag-flucht.0": "Ferret a besoin d’une pelle, et le cuistot en échange une contre du sucre. Achète un sac chez Kipper.",
  "oddjob.chain.stalag-flucht.1": "La pelle est à lui. Ferret creuse sous sa couchette : fais le guet devant sa porte.",
  "oddjob.chain.stalag-flucht.2": "Nobby parle aux gardiens. Planque ce paquet dans son bureau avant qu’il parle encore.",
  "oddjob.chain.stalag-flucht.0.done": "Le cuistot soupèse le sucre et hoche la tête. La pelle est sous les pommes de terre.",
  "oddjob.chain.stalag-flucht.1.done": "Ferret s’essuie les mains. « Encore trente centimètres. Personne n’a rien vu. »",
  "oddjob.chain.stalag-flucht.2.done": "Nobby passe la nuit à s’expliquer. Ferret te donne sa meilleure pelle.",
  "oddjob.chain.shankton.title": "La quête de Preacher",
  "oddjob.chain.shankton.0": "Weasel a plumé Preacher de la quête de la chapelle aux cartes. Reprends-la-lui au Menteur.",
  "oddjob.chain.shankton.1": "Preacher envoie l’argent à Smokes, qui le doit à la chapelle. Remets-lui ce colis.",
  "oddjob.chain.shankton.2": "Weasel garde des cartes marquées dans sa cellule. Un appel anonyme devrait régler ça.",
  "oddjob.chain.shankton.0.done": "Weasel retourne sa dernière carte et jure. Preacher compte chaque pièce deux fois.",
  "oddjob.chain.shankton.1.done": "Smokes soupèse le colis et sourit. « Dis à Preacher qu’on est quittes. »",
  "oddjob.chain.shankton.2.done": "Les gardiens retournent la cellule de Weasel. « Dieu te bénisse », dit Preacher. « Je te dois bien ça. »",
  "oddjob.chain.san-pancho.title": "L’anniversaire de Toro",
  "oddjob.chain.san-pancho.0": "C’est bientôt l’anniversaire de Toro, et il faut brasser pour la fête. Achète un sac de sucre chez Flaco.",
  "oddjob.chain.san-pancho.1": "Pas de fête sans gâteau. La sœur de Toro en apporte un à la prochaine visite : fais-le entrer.",
  "oddjob.chain.san-pancho.2": "Toro veut un bras de fer pour son anniversaire, et il veut gagner. Laisse-le faire.",
  "oddjob.chain.san-pancho.0.done": "Flaco te passe le sucre avec un clin d’œil. La cuvée bouillonne sous la couchette de Toro.",
  "oddjob.chain.san-pancho.1.done": "Le gâteau porte son nom en sucre rose. Toro en a presque les larmes aux yeux.",
  "oddjob.chain.san-pancho.2.done": "Toro lève ton bras avec le sien. « Mon meilleur anniversaire en taule ! » Il te donne un tournevis.",
  "oddjob.chain.irongate.title": "Le message de Gull",
  "oddjob.chain.irongate.0": "Gull fait des signaux à son frère sur le continent avec un sifflet de gardien, la nuit. Piques-en un.",
  "oddjob.chain.irongate.1": "Son frère a répondu. Gull doit faire passer ce colis à Kipper, sans être vu : glisse-le dans son bureau.",
  "oddjob.chain.irongate.2": "Barnacle surveille la côte la nuit. Occupe-le aux dames, et laisse-le gagner.",
  "oddjob.chain.irongate.0.done": "Trois courts, un long. Au loin sur l’eau, une lumière clignote en retour.",
  "oddjob.chain.irongate.1.done": "Kipper trouve le colis et fait un signe de tête à Gull à travers la cantine.",
  "oddjob.chain.irongate.2.done": "Barnacle savoure sa victoire pendant que le bateau passe. « Je te dois un service », dit Gull.",

