  "trophy.cleanSr": "fuite réussie",
  "ach.cleanGetaway": "Envolé pour de bon",
  "ach.cleanGetaway.d": "Après une évasion, continuer à courir jusqu’à être en lieu sûr.",
  "ach.withoutTrace": "Sans laisser de traces",
