  "ach.changeOfClothes": "Changement de tenue",
  "ach.changeOfClothes.d": "Une fuite réussie dans des vêtements pris sur un fil à linge.",
  "ach.outOfTheLight": "Hors du faisceau",
  "ach.outOfTheLight.d": "Pris dans le projecteur de l’hélicoptère, et en lieu sûr quand même.",
  "ach.getawayDriver": "Chauffeur attitré",
  "ach.getawayDriver.d": "Rejoindre la voiture du cousin Lou, dehors, pour une fuite réussie.",
  "ach.longArm": "Le bras de la loi",
  "ach.longArm.d": "Te faire reprendre après une évasion.",
  "ach.soClose": "Si près du but",
  "ach.soClose.d": "Te faire reprendre avec les neuf dixièmes du chemin derrière toi.",
  "ach.allClear": "Libre partout",
  "ach.allClear.d": "Une fuite réussie depuis chaque prison.",
  "look.mhBeanie": "Bonnet forêt",
  "help.manhunt.t": "La traque",
  "help.manhunt.hook": "Passé le mur : file pour de bon",
  "help.manhunt.sum": "Passé le mur, l’évasion compte déjà. Continue à courir dehors jusqu’en lieu sûr pour filer pour de bon : une étoile sur l’étagère des médailles.",
  "help.manhunt.steps": "Sur la carte d’évasion, choisis Continuer à courir (Passer garde la fin telle quelle).\nLa flèche en haut montre le chemin vers le lieu sûr, et sa distance.\nReste hors des cônes de vision des poursuivants. Dans une haie ou une buse, ne bouge plus : aucun œil ne t’y trouve (si tu bouges, on te voit de près).\nArrive avant qu’ils ne t’attrapent.",
  "help.manhunt.tl": "Avance|Jusqu’à 10 s si personne ne t’a vu partir\nL’alerte|Les poursuivants sortent, vers là où tu seras\nPeu après|Des chiens sur ta piste, des barrages, l’hélicoptère\nPlus tard|Les recherches s’élargissent : des yeux plus perçants, la lumière sur les haies",
  "help.manhunt.lh": "Ce qui aide",
  "help.manhunt.list": "Un fil à linge : d’autres vêtements. On ne te reconnaît que de près, et les chiens perdent ta piste (sans l’uniforme de gardien, on te reconnaît d’un peu plus loin).\nUn gué efface ta piste.\nUn caillou lancé (Espace) attire les poursuivants là où il tombe.\nDu séché, du poivre ou du séché somnifère pour un chien à portée.\nUne pince te fait passer un grillage.\nLa voiture du cousin Lou, si un appel l’a prévue, attend plus près.\nUn membre de ta bande sorti avec toi fait le guet et siffle.",
  "help.manhunt.warn": "Le gravier et les voies ferrées sont bruyants sous les pieds.\nLa lumière de l’hélicoptère te trouve partout, sauf immobile à couvert.\nLe flair d’un chien te trouve de près, caché ou non, et il suit ta piste.",
  "help.manhunt.nums": "10 s|d’avance au plus\n3 cases|on te reconnaît dans d’autres habits\n60 s|ta piste reste fraîche",
  "help.manhunt.more": "Vu en partant (confinement, poursuite, mutinerie) : aucune avance.\nHors des routes tu vas moins vite, encore moins à couvert.\nUn uniforme de gardien ne les trompe que jusqu’à ce que les recherches s’élargissent deux fois ; dans la lumière de l’hélicoptère, rien ne les trompe.\nUn poursuivant à tes trousses, ou le maître d’un chien qui t’a trouvé, te suit à couvert.\nUne libération légale (papiers falsifiés, conditionnelle) sort à pied : pas de traque.\nRepris, l’évasion compte quand même : la carte dit à quel point tu étais près. Quitter une traque compte comme repris.\nL’évasion du jour s’arrête au mur.",
  "lesson.manhunt.t": "La traque",
  "lesson.manhunt.d": "Passé le mur de Center Perks : filer dans la voiture de Lou",
  "lesson.manhunt.run": "Tu es passé par-dessus le mur et on t’a vu partir. Éloigne-toi du mur dans les bois : la flèche en haut montre la voiture de Lou",
  "lesson.manhunt.hide": "Un poursuivant arrive le long du mur. Entre dans le fourré et ne bouge plus jusqu’à ce qu’il soit passé",
  "lesson.manhunt.clothes": "Prends des vêtements sur le fil à linge près de la maisonnette : on ne te reconnaîtra que de près, et les chiens perdront ta piste",
  "lesson.manhunt.lou": "Maintenant, rejoins la voiture de Lou sur le chemin : monte et tu es sauvé",
  "lesson.manhunt.caught": "Repris",
  "lesson.manhunt.caughtSub": "Un poursuivant t’a eu trop longtemps dans son champ de vision. Recommence la leçon",
