  "holiday.dayD.eggHunt": "Des œufs en chocolat cachés dans les bureaux des détenus et dans la cour : trouve-les avant eux (à 22:00, ceux qui restent sont à eux). Mange-les ou vends-les. Gigot au dîner.",
  "holiday.dayD.waterFight": "15:00–15:30, des tuyaux sur le terrain de sport (l’heure d’exercice) : un gardien trempé n’y voit qu’à {n} cases. Une glace au comptoir de la cantine jusqu’à 15:30 ; barbecue au dîner.",
  "holiday.dayD.costumeNight": "Un costume au comptoir de la cantine, une citrouille dans le congélateur de la cuisine, jusqu’à 21:00 (sculpte-la en cuisine). Dès 19:00, le costume ne trompe personne, mais chaque détenu près de toi rit.",
  "holiday.dayD.christmasDay": "Un cadeau sous le sapin, au comptoir de la cantine, jusqu’à 22:00 : offre-le à quelqu’un. Dîner de Noël à 17:00.",
  "holiday.dayD.newYearsEve": "Feu d’artifice à minuit : pendant dix minutes, il couvre tous les bruits que tu fais.",
  "holiday.pa.eggHunt": "Joyeuses Pâques ! Des œufs sont cachés dans la prison. Gigot ce soir.",
  "holiday.pa.waterFight": "C’est l’été ! Bataille d’eau sur le terrain de sport à quinze heures, barbecue au dîner. Des glaces au comptoir.",
  "holiday.pa.costumeNight": "Joyeux Halloween. Soirée déguisée dès dix-neuf heures, costumes au comptoir. Personne ne sera dupe.",
  "holiday.pa.christmasDay": "Joyeux Noël à tous ! Des cadeaux sous le sapin, dîner de Noël à dix-sept heures.",
  "holiday.pa.newYearsEve": "C’est le réveillon ! Feu d’artifice à minuit. Bouchons d’oreilles non fournis.",
  "holiday.paStart.waterFight": "Les tuyaux sont ouverts. Gardiens, attention à vos casquettes.",
  "holiday.paStart.costumeNight": "La soirée déguisée commence. Merci de ne pas effrayer les gardiens.",
  "holiday.paStart.newYearsEve": "Bonne année ! Dix minutes de feu d’artifice, puis au lit.",
