  "help.holidays.t": "Les fêtes",
  "help.holidays.hook": "Pâques, l’été, Halloween, Noël",
  "help.holidays.sum": "Une partie commencée pendant une fête la garde : décorations, sa journée sur la carte du directeur, friandises et trophées.",
  "help.holidays.lh": "Les quatre fêtes",
  "help.holidays.list": "Pâques (du vendredi saint au lundi de Pâques) : une chasse aux œufs. Des œufs en chocolat se cachent dans les bureaux des détenus et dans la cour ; mange-les ou vends-les. Gigot au dîner.\nL’été (juillet et août) : une bataille d’eau sur le terrain de sport à 15:00 (l’heure d’exercice), et les gardiens trempés n’y voient qu’à 2 cases. Des glaces, un barbecue, plus de canicules.\nHalloween (du 24 octobre au 2 novembre) : soirée déguisée. Le costume ne trompe personne, mais les détenus près de toi rient et t’apprécient davantage. Sculpte une citrouille en cuisine.\nNoël et Nouvel An (du 15 décembre au 6 janvier) : un cadeau à offrir, le dîner de Noël, puis un feu d’artifice à minuit qui couvre tous les bruits.",
  "help.holidays.lh2": "Dans les Réglages",
  "help.holidays.list2": "Selon la date : une nouvelle partie prend la fête du calendrier.\nAu choix : n’importe quelle fête, tout de suite.\nAucune : pas de fêtes du tout.",
  "help.holidays.nums": "Jour 2|le premier jour de la fête\n7 jours|avant qu’elle revienne\n2 cases|ce que voit un gardien trempé",
  "help.holidays.tip": "Les friandises attendent au comptoir de la cantine (la citrouille dans le congélateur de la cuisine) : ouvre-le et prends-en une, une fois par jour, tant que dure le jour de fête.",
  "help.holidays.more": "Une partie garde la fête de son début, même une fois la date passée.\nL’Évasion du jour se joue sans, la même pour tous ; seules ses décorations suivent la date.\nLe Bloc d’entraînement ne fête rien.\nLes décorations sont juste pour le décor : rien ne te barre la route.",
